from django.test import TestCase, override_settings

from .scientific_engine import DeepContentSniffer


def sniff(text: str, filename: str = "input.txt") -> str:
    fmt, err = DeepContentSniffer.sniff_format(text.encode("utf-8"), filename)
    assert err is None, err
    return fmt


class FormatSniffingRegressionTests(TestCase):
    """Regressions for format detection bugs found in the October 2026 audit."""

    def test_orca_input_with_hash_comments_is_not_gaussian(self):
        text = (
            "# Generated by iLoveChem Studio\n"
            "# Electron count: 42 | Parity verified\n"
            "! B3LYP def2-SVP opt freq D3BJ\n"
            "%maxcore 2048\n%pal nprocs 8 end\n\n"
            "* xyz 0 1\n  C  0.0  0.0  0.0\n  H  0.0  0.0  1.09\n*"
        )
        self.assertEqual(sniff(text, "calculation.inp"), "inp")

    def test_gaussian_input_still_detected(self):
        text = "%nprocshared=8\n%mem=16GB\n#p B3LYP/def2-SVP opt freq\n\nTitle\n\n0 1\nC 0 0 0\n"
        self.assertEqual(sniff(text, "mol.gjf"), "gjf")
        self.assertEqual(sniff("# B3LYP/6-31G* opt\n\nTitle\n\n0 1\nC 0 0 0\n", "mol.com"), "gjf")

    def test_xyz_with_hash_comment_is_xyz(self):
        text = "3\n# opt water geometry\nO 0 0 0\nH 0 0 1\nH 0 1 0\n"
        self.assertEqual(sniff(text, "water.xyz"), "xyz")

    def test_pdb_text_with_branched_is_not_pdbqt(self):
        text = (
            "HEADER    TRANSFERASE\nCOMPND   2 MOLECULE: BRANCHED GLYCAN ROOTED\n"
            "ATOM      1  N   ALA A   1      10.000  10.000  10.000  1.00 20.00           N\n"
        )
        self.assertEqual(sniff(text, "x.pdb"), "pdb")

    def test_real_pdbqt_is_pdbqt(self):
        text = "REMARK  1\nROOT\nATOM      1  C   LIG A   1       0.000   0.000   0.000  0.00  0.00    +0.000 C\nENDROOT\nTORSDOF 0\n"
        self.assertEqual(sniff(text, "lig.pdbqt"), "pdbqt")

    def test_smiles_with_lowercase_heteroatoms(self):
        self.assertEqual(sniff("c1ccsc1", "input.xyz"), "smi")   # thiophene
        self.assertEqual(sniff("c1ccoc1", "input.xyz"), "smi")   # furan
        self.assertEqual(sniff("[Fe]", "input.xyz"), "smi")


class SiteMetadataTests(TestCase):
    @override_settings(SITE_URL="https://example.org")
    def test_sitemap_uses_configured_https_origin_and_lists_about(self):
        body = self.client.get("/sitemap.xml", HTTP_HOST="evil.example").content.decode()
        self.assertIn("https://example.org/about/", body)
        self.assertNotIn("evil.example", body)
        self.assertNotIn("http://", body.replace("http://www.sitemaps.org", ""))

    @override_settings(SITE_URL="https://example.org")
    def test_robots_points_to_configured_sitemap(self):
        body = self.client.get("/robots.txt").content.decode()
        self.assertIn("Sitemap: https://example.org/sitemap.xml", body)

    def test_public_source_bundle_and_history_endpoints_are_gone(self):
        self.assertEqual(self.client.get("/audit/bundle/").status_code, 404)
        self.assertEqual(self.client.get("/api/history/").status_code, 404)
